package com.hbm.client.oilfracking;
import com.hbm.machine.oilfracking.*;import mezz.jei.api.*;import mezz.jei.api.gui.builder.IRecipeLayoutBuilder;import mezz.jei.api.gui.drawable.IDrawable;import mezz.jei.api.gui.ingredient.IRecipeSlotsView;import mezz.jei.api.helpers.IGuiHelper;import mezz.jei.api.recipe.*;import mezz.jei.api.recipe.category.IRecipeCategory;import mezz.jei.api.registration.*;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.item.ItemStack;
@JeiPlugin public final class FrackingJeiPlugin implements IModPlugin {
 static final RecipeType<FrackingViews.Extraction> TYPE=RecipeType.create("hbm","oil_fracking",FrackingViews.Extraction.class);@Override public ResourceLocation getPluginUid(){return ResourceLocation.parse("hbm:oil_fracking_jei");}@Override public void registerCategories(IRecipeCategoryRegistration e){e.addRecipeCategories(new Category(e.getJeiHelpers().getGuiHelper()));}@Override public void registerRecipes(IRecipeRegistration e){e.addRecipes(TYPE,FrackingViews.recipes());}@Override public void registerRecipeCatalysts(IRecipeCatalystRegistration e){e.addRecipeCatalysts(TYPE,FrackingContent.ITEM.get());}
 private static final class Category implements IRecipeCategory<FrackingViews.Extraction>{final IDrawable background,icon;Category(IGuiHelper h){background=h.createBlankDrawable(166,84);icon=h.createDrawableItemStack(new ItemStack(FrackingContent.ITEM.get()));}@Override public RecipeType<FrackingViews.Extraction> getRecipeType(){return TYPE;}@Override public Component getTitle(){return Component.translatable("recipe.hbm.oil_fracking");}@Override public IDrawable getBackground(){return background;}@Override public IDrawable getIcon(){return icon;}@Override public void setRecipe(IRecipeLayoutBuilder b,FrackingViews.Extraction r,IFocusGroup focus){b.addSlot(RecipeIngredientRole.CATALYST,8,24).addItemStack(r.deposit()).addRichTooltipCallback((slot,t)->t.add(FrackingViews.depletion(r)));b.addSlot(RecipeIngredientRole.CATALYST,38,24).addItemStack(new ItemStack(FrackingContent.ITEM.get()));b.addSlot(RecipeIngredientRole.INPUT,66,24).addItemStack(r.solution());b.addSlot(RecipeIngredientRole.OUTPUT,92,15).addItemStack(r.oil());b.addSlot(RecipeIngredientRole.OUTPUT,120,15).addItemStack(r.gas()).addRichTooltipCallback((slot,t)->t.add(FrackingViews.gas(r)));if(!r.bedrock())b.addSlot(RecipeIngredientRole.OUTPUT,92,43).addItemStack(r.depleted()).addRichTooltipCallback((slot,t)->t.add(FrackingViews.depletion(r)));}@Override public void draw(FrackingViews.Extraction r,IRecipeSlotsView slots,GuiGraphics g,double x,double y){g.drawString(com.hbm.client.gui.font.LegacyFonts.get(),Component.translatable("gui.hbm.oil_drill.interval",r.config().delay()),3,66,0x404040,false);g.drawString(com.hbm.client.gui.font.LegacyFonts.get(),Component.translatable("gui.hbm.oil_drill.consumption",r.config().consumption()),3,76,0x404040,false);}}
}
